VALUES
('art-museum', '美术馆', 'indoor', 'studio', 'ph-palette', '在艺术里，把光影走成一幅画', '适合白天自然光，空旷的现代展厅、几何展墙与挑高空间，天光从高处漫射而下。人在画前驻足，是最安静高级的构图。', '{"lut":"mist"}', '["利用展墙延伸线做引导线构图","让人物站在天窗光束下，突出轮廓","大光圈虚化背景画作，突出主体"]', '["https://picsum.photos/seed/scene-art-museum/600/800"]', '美术馆 / 博物馆 / 艺术画廊', '白天 10:00-16:00', 'portrait', '[]', 1001, 1, 1788422640000, 1788422640000),
('city-mall', '商场购物', 'indoor', 'cafe', 'ph-shopping-bag', '拎着战利品，把逛街拍成秀场', '适合全天候，明亮中庭、电梯间与玻璃幕墙，暖色灯光通透敞亮。逛街拎袋的瞬间，是最自然的都市时尚图景。', '{"lut":"warm_film"}', '["利用扶梯做纵深，拍出层次","橱窗灯光做轮廓光，点亮发丝","中庭俯拍强调空间开阔"]', '["https://picsum.photos/seed/scene-city-mall/600/800"]', '购物中心 / 中庭 / 扶梯电梯间', '全天 10:00-21:00', 'street', '[]', 1002, 1, 1788422640000, 1788422640000),
('hotpot-restaurant', '火锅暖席', 'indoor', 'cafe', 'ph-cooking-pot', '一锅滚烫，把热气拍成团圆', '适合晚上，氤氲蒸汽与暖黄灯光下，围炉涮菜是最治愈的烟火气。热气腾腾的画面自带温度感。', '{"lut":"warm_film"}', '["逆着蒸汽拍，让热气透光发亮","暖色顶灯做主光源，规避顶光阴影","加入碰杯、涮菜的手部动作"]', '["https://picsum.photos/seed/scene-hotpot-restaurant/600/800"]', '火锅店 / 传统食肆 / 家宴圆桌', '晚上 18:00-22:00', 'food', '[]', 1003, 1, 1788422640000, 1788422640000),
('izakaya', '日料居酒屋', 'indoor', 'cafe', 'ph-martini', '一壶清酒，把夜色暖成微醺', '适合夜晚，暖红衣灯与木质吧台、串烧与清酒构成温暖慵懒的氛围。昏黄灯光下最有故事感。', '{"lut":"vintage"}', '["吧台灯做侧光，勾勒脸部轮廓","利用酒瓶阵列做前景虚化","低感光手持，保持灯笼暖色"]', '["https://picsum.photos/seed/scene-izakaya/600/800"]', '日式居酒屋 / 烧鸟店 / 深夜食堂', '晚上 19:00-24:00', 'night', '[]', 1004, 1, 1788422640000, 1788422640000),
('gym', '健身房', 'indoor', 'studio', 'ph-dumbbell', '在器械之间，把自律拍成光', '适合上午或傍晚，落地玻璃透进的斜光洒在器械与镜面上。冷色调现代空间，充满力量与活力。', '{"lut":"cinematic"}', '["逆光拍剪影，突出训练轮廓","利用镜面反射增加画面层次","抓拍运动瞬间，凝固汗水"]', '["https://picsum.photos/seed/scene-gym/600/800"]', '健身房 / 瑜伽馆 / 户外训练场', '上午 08:00-11:00 或傍晚 17:00-19:00', 'portrait', '[]', 1005, 1, 1788422640000, 1788422640000),
('dance-studio', '舞蹈练习室', 'indoor', 'studio', 'ph-footprints', '一步腾空，把梦想跳出光', '适合带大镜面的练习室，逆光剪影下舞者跃动，聚光灯把深色空间照亮，自由热烈。', '{"lut":"cinematic"}', '["低速快门 + 高速闪光，捕捉腾空瞬间","利用镜面拓展空间感","逆光拍轮廓，突出肢体线条"]', '["https://picsum.photos/seed/scene-dance-studio/600/800"]', '舞蹈室 / 排练厅 / 镜面练功房', '白天或晚上 09:00-21:00', 'portrait', '[]', 1006, 1, 1788422640000, 1788422640000),
('tea-room', '茶室禅意', 'indoor', 'cafe', 'ph-leaf', '一盏清茶，把喧嚣煮成禅', '适合白天，竹帘透进的柔和日光洒在茶具上，茶烟袅袅。素雅中式空间，是宁静致远的拍摄场景。', '{"lut":"fuji"}', '["用茶烟做前景，增加氛围与动感","侧光勾勒器皿与手部细节","大光圈虚化背景，突出茶道之美"]', '["https://picsum.photos/seed/scene-tea-room/600/800"]', '茶室 / 禅意庭院 / 中式茶馆', '白天 10:00-16:00', 'still-life', '[]', 1007, 1, 1788422640000, 1788422640000),
('balcony-garden', '阳台绿植', 'indoor', 'home', 'ph-plant', '一方阳台，把晨光种成小森林', '适合上午或午后，洒满阳光的居家阳台，绿植环绕与藤编座椅构成治愈角落。清新自然，是家里最出片的地方。', '{"lut":"fresh"}', '["让晨光穿过叶片，拍出通透绿意","用绿植做前景，营造层次","藤编座椅增加生活气息"]', '["https://picsum.photos/seed/scene-balcony-garden/600/800"]', '家里阳台 / 露台 / 绿植角落', '上午 07:00-10:00 或午后 15:00-17:00', 'still-life', '[]', 1008, 1, 1788422640000, 1788422640000),
('heritage-courtyard', '老宅天井', 'indoor', 'studio', 'ph-buildings', '四方的天空，把时光留在天井', '适合白天，青砖老宅的四方形天井从天而落的光线，梁柱与侧柏剪影，中式建筑美学，静谧怀旧。', '{"lut":"cinematic"}', '["仰拍天井，形成框式构图","利用梁柱阴影分割画面","人物置于光束下，突出古典"]', '["https://picsum.photos/seed/scene-heritage-courtyard/600/800"]', '老宅 / 四合院 / 古建筑天井', '白天 10:00-15:00 光线最佳', 'portrait', '[]', 1009, 1, 1788422640000, 1788422640000),
('retro-barber', '复古理发馆', 'light', 'neon', 'ph-scissors', '复古旋转椅，把街头拍成画报', '适合夜晚，老式理发椅与霓虹灯牌，暖橙与粉蓝撞色，胶片质感的复古摩登。', '{"lut":"vintage"}', '["霓虹灯牌做轮廓光或补色","老式座椅做前景，增加年代感","低感光，保留灯牌色彩"]', '["https://picsum.photos/seed/scene-retro-barber/600/800"]', '复古理发店 / 老式美容院 / 潮牌理发馆', '晚上 19:00-23:00', 'night', '[]', 1010, 1, 1788422640000, 1788422640000),
('night-market', '夜市烟火', 'light', 'neon', 'ph-chalkboard', '一街宵夜，把夜色烫成人间', '适合夜晚，彩色霓虹招牌与鼎沸摊位，热气与灯光交织，是烟火气最浓的街头食堂。', '{"lut":"warm_film"}', '["逆着灯光拍蒸汽与烟雾","暖色顶光下单张抓拍人群","食物做前景，增加生活气息"]', '["https://picsum.photos/seed/scene-night-market/600/800"]', '夜市 / 小吃街 / 大排档', '晚上 19:00-24:00', 'food', '[]', 1011, 1, 1788422640000, 1788422640000),
('dawn-mist', '清晨雾光', 'light', 'window-light', 'ph-cloud-sun', '雾起林间，把清晨拍成水墨', '适合清晨 6-8 点，薄雾弥漫的道路与树林，第一缕朝阳穿雾而落，柔和青白金辉，缥缈朦胧。', '{"lut":"mist"}', '["逆光朝雾气拍，产生光束","降低饱和度，保持晨雾的青灰","带人物剪影，增加画面焦点"]', '["https://picsum.photos/seed/scene-dawn-mist/600/800"]', '晨间小路 / 湖边 / 山间', '清晨 05:30-08:00', 'landscape', '[]', 1012, 1, 1788422640000, 1788422640000),
('road-sunset', '落日公路', 'light', 'sunset-backlight', 'ph-road-horizon', '一路向前，把晚霞开成金浪', '适合日落前后 30 分钟，笔直公路伸向落日，金色晚霞铺满，逆光剪影在路上，辽阔浪漫。', '{"lut":"cinematic"}', '["降低机位贴地，强化公路延伸","对天空测光，人物做剪影","抓拍行走姿态，留意车辆安全"]', '["https://picsum.photos/seed/scene-road-sunset/600/800"]', '郊外公路 / 草原道路 / 沿海公路', '黄昏 17:30-19:00', 'landscape', '[]', 1013, 1, 1788422640000, 1788422640000),
('street-style', '城市街拍', 'outdoor', 'urban', 'ph-hoodie', '横穿斑马线，把街头走出气场', '适合白天或黄昏，都市街道的霓虹与建筑交错，潮人穿梭于斑马线，时尚电影感。', '{"lut":"cinematic"}', '["背景干净的墙面做简约背景","抓拍走动瞬间，凝固姿态","利用光影交界做明暗层次"]', '["https://picsum.photos/seed/scene-street-style/600/800"]', '商业街区 / 人行道 / 天桥下', '白天 10:00-17:00 或黄昏', 'street', '[]', 1014, 1, 1788422640000, 1788422640000),
('hutong', '胡同老巷', 'outdoor', 'urban', 'ph-buildings', '穿过老巷，把岁月留在砖墙上', '适合午后，青灰砖墙与晾衣绳，斜光洒在石板路，市井烟火与怀旧气息。', '{"lut":"vintage"}', '["利用砖墙斑驳做质感背景","逆光让晾衣绳透亮","低角度仰拍屋檐与天际线"]', '["https://picsum.photos/seed/scene-hutong/600/800"]', '老街 / 胡同 / 小巷子', '午后 14:00-17:00', 'street', '[]', 1015, 1, 1788422640000, 1788422640000),
('campus', '校园操场', 'outdoor', 'urban', 'ph-graduation-cap', '绿茵红道，把青春撒成光', '适合下午，绿茵操场与红色跑道，阳光下奔跑的身影，通透清新，青春活力。', '{"lut":"fresh"}', '["抓拍奔跑跳跃的动感瞬间","利用跑道线条做引导线","逆光给人物镀上金边"]', '["https://picsum.photos/seed/scene-campus/600/800"]', '校园操场 / 跑道 / 草坪', '下午 15:00-18:00', 'portrait', '[]', 1016, 1, 1788422640000, 1788422640000),
('lakeside', '湖畔河堤', 'outdoor', 'seaside', 'ph-waves', '水天一色，把心事放回湖面', '适合清晨或黄昏，波光粼粼的湖畔河堤，水天一色的柔和光，散步剪影宁静开阔。', '{"lut":"cinematic"}', '["顺水面拍倒影，形成对称构图","黄昏捕捉湖面金光","人物靠堤岸，增加纵深"]', '["https://picsum.photos/seed/scene-lakeside/600/800"]', '湖畔 / 河堤 / 水库边', '清晨 06:00-08:00 或黄昏 17:00-19:00', 'landscape', '[]', 1017, 1, 1788422640000, 1788422640000),
('park-lawn', '公园草地', 'outdoor', 'forest', 'ph-tree', '草绿天蓝，把野餐摆成画', '适合白天，开阔翠绿草坪与野餐垫，午后斑驳树影，风筝与欢笑，惬意治愈。', '{"lut":"fresh"}', '["让树影斑驳落在人物身上","低角度俯拍野餐布景","抓拍奔跑或躺卧的自然状态"]', '["https://picsum.photos/seed/scene-park-lawn/600/800"]', '公园草坪 / 露营草地 / 野餐区', '白天 09:00-16:00', 'landscape', '[]', 1018, 1, 1788422640000, 1788422640000),
('flower-field', '花海春日', 'outdoor', 'forest', 'ph-flower', '半亩花田，把春天穿在身上', '适合早晨或傍晚，漫山花海随风摇曳，逆光下的花田与人影，浪漫梦幻。', '{"lut":"pastel"}', '["逆光让花瓣透亮泛光","压低机位拍花海纵深","人物站花径尽头，融入花景"]', '["https://picsum.photos/seed/scene-flower-field/600/800"]', '花田 / 樱花林 / 油菜花田', '早晨 07:00-09:00 或黄昏 16:00-18:00', 'landscape', '[]', 1019, 1, 1788422640000, 1788422640000),
